import { lazy } from 'react';
import { ClipboardList as IcClipboardList, Database as IcDatabase, FileText as IcFileText, Package as IcPackage, Wrench as IcWrench } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Master Data — hub page for the Settings menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 5 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'MasterDataCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
// ⚠ The Settings-scoped view: the same MasterSetup screen with the employee
// masters excluded, because those are managed from Employees.
const MasterSetup = lazy(() => import('../views/SettingsMasterSetup'));
const ProductSetup = lazy(() => import('./ProductSetup'));
const DocumentSetup = lazy(() => import('./DocumentSetup'));
const OrderPolicy = lazy(() => import('./OrderPolicy'));
const AssetMaintenance = lazy(() => import('./AssetMaintenance'));

export const TABS = [
  { id: 'masters', label: 'Master Setup', icon: IcDatabase, page: 'MasterSetup', Component: MasterSetup },
  { id: 'products', label: 'Product Setup', icon: IcPackage, page: 'ProductSetup', Component: ProductSetup },
  { id: 'documents', label: 'Document Setup', icon: IcFileText, page: 'DocumentSetup', Component: DocumentSetup },
  { id: 'orders', label: 'Order Policy', icon: IcClipboardList, page: 'OrderPolicy', Component: OrderPolicy },
  { id: 'assets', label: 'Asset Maintenance', icon: IcWrench, page: 'AssetMaintenance', Component: AssetMaintenance },
];

export default function MasterDataCenter({ setPage }) {
  return (
    <TabHub
      icon={IcDatabase}
      eyebrow="Settings"
      title="Master Data"
      subtitle="Shared reference data: masters, products, document numbering, order policy and asset maintenance"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
